refentry.refsect1:
  &reftitle.examples;



    Пример замены символов функцией strtr


<?php

$original = "He1Lo, w0rld!";

// При вызове с тремя аргументами функция strtr() заменяет символы побайтово.
$result = strtr($original, "1L0", "llo");
echo $result;


    &example.outputs;


Hello, world!






   Следующий пример показывает поведение функции strtr
   при вызове только с двумя аргументами. Обратите внимание
   на приоритет замен — символ "h" не участвует в поиске,
   поскольку массив содержит более длинные совпадения, — и как после замены новый текст
   больше не участвует в поиске.


   Пример замены подстрок при вызове функции strtr с двумя аргументами


<?php

$replace_pairs = ["h" => "-", "hello" => "hi", "hi" => "hello"];
echo strtr("hi all, I said hello", $replace_pairs);


   &example.outputs;


hello all, I said hi





   Функция strtr работает в двух режимах:
   при вызове с тремя аргументами выполняется побайтовая замена,
   а при вызове с двумя заменяются и более длинные подстроки.


   Сравнение поведения функции strtr


<?php

// Однобайтовые символы
$singlebyte_string = "baab";
echo strtr($singlebyte_string, "ab", "01"), "\n"; // Побайтовая замена

$replace_pairs = ["ab" => "01"];
echo strtr($singlebyte_string, $replace_pairs), "\n"; // Замена подстрок

// Многобайтовые символы
$multibyte_string = "Ä"; // В кодировке UTF-8 символ кодируется двумя байтами: "\xC3\x84"

$result = strtr($multibyte_string, 'Ä', 'A');
echo bin2hex($result), "\n"; // "4184", где "41" — байт символа "A", которым заменился байт "c3",
                             // а "84" — байт, которому не нашлось замены в третьем аргументе;
                             // последовательность байтов теперь невозможно интерпретировать
                             // как символ в кодировке UTF-8
$replace_pairs = ['Ä' => 'A'];
echo strtr($multibyte_string, $replace_pairs); // Правильный перевод многобайтовой строки


   &example.outputs;


1001
ba01
4184
A
